  static function prompts(){
    $rules="\n\nDATA (from our automated audit – use only these facts, never invent numbers):\nWebsite: {{website}}\nWebsite score: {{web_score}}/100\nWebsite audit (JSON): {{website_audit}}\nGoogle Maps score: {{map_score}}/100\nGoogle Maps audit (JSON): {{map_audit}}\nTop competitors on Google Maps for \"{{keyword}}\": {{competitors}}\n\nABOUT US\nAgency: {{agency_name}} ({{agency_website}})\nServices: {{services}}\n";
    $web="Write a professional Website & Google Maps audit report for {{business_name}} – a {{category}} business in {{city}}.".$rules."Yearly package fee: {{currency_symbol}}{{yearly_fee}} per year\n\nWRITE THESE SECTIONS (each starts with <h2>):\n1. Executive Summary – 3-4 friendly but direct sentences. Mention both scores.\n2. Website Issues Holding You Back – a <table> with columns Issue | Why it matters for your business | Priority (High/Medium/Low). Only include checks that failed or have warnings. Explain in plain language (lost calls, lower Google ranking, lost trust).\n3. Google Maps Visibility Gaps – compare their rating, review count, photos and position with the competitors. Explain why competitors are getting the calls.\n4. What We Will Fix For You – bullet list mapping each problem to our service.\n5. The Numbers – estimate a realistic value of ONE converted lead/customer for a {{category}} business in {{city}} in {{currency}} and state the assumption. Calculate n = yearly fee ÷ lead value (round up). Show a <table>: Avg. customer value | Our yearly fee | Customers needed to break even (n) | Conservative extra enquiries per month. Then one bold line: \"Just n new customers in a whole year pays for the entire service – everything after that is profit.\"\n6. Next Step – a short persuasive call to action: reply on WhatsApp or email to book a free 15-minute strategy call.\n\nTone: confident, helpful, simple English, no jargon, no guarantees of #1 rankings, no fake statistics. Length 900-1300 words.";
    $noweb="Write a professional Google Maps audit & website proposal report for {{business_name}} – a {{category}} business in {{city}} that currently has NO website.".$rules."Website development fee: {{currency_symbol}}{{website_fee}} (one time)\nYearly SEO & Google Maps package: {{currency_symbol}}{{yearly_fee}} per year\n\nWRITE THESE SECTIONS (each starts with <h2>):\n1. Executive Summary – 3-4 sentences. Mention the Google Maps score and that they have no website.\n2. Why Not Having a Website Costs You Customers – 4-6 bullet points specific to a {{category}} business (trust, Google ranking signals, enquiries, competitors with websites).\n3. Google Maps Visibility Gaps – a <table> Issue | Impact | Priority, then compare with competitors (rating, reviews, photos, position).\n4. What We Will Build & Fix – website + Google Business Profile optimisation, as a bullet list.\n5. The Numbers – estimate a realistic value of ONE converted customer for a {{category}} business in {{city}} in {{currency}} and state the assumption. Calculate n = (website fee + yearly fee) ÷ customer value (round up). Show a <table>: Avg. customer value | Total first-year investment | Customers needed to break even (n). Then one bold line: \"Just n new customers pays for your website and a full year of Google growth.\"\n6. Next Step – mention that our detailed website proposal is attached, and invite them to reply on WhatsApp or email for a free 15-minute call.\n\nTone: confident, helpful, simple English, no jargon, no guarantees, no fake statistics. Length 800-1200 words.";
    $wa="Hello {{business_name}} team 👋\n\nThis is {{sender_name}} from {{agency_name}}. We ran a free audit of your Google Maps listing and website, and found a few things that may be costing you customer enquiries.\n\nI have attached your personalised report (PDF) – please have a look, it takes just 2 minutes.\n\nReport link: {{report_link}}\n\nShall I explain the key points on a quick call?";
    $wan="Hello {{business_name}} team 👋\n\nThis is {{sender_name}} from {{agency_name}}. We checked your Google Maps listing and noticed you don't have a website yet – many customers search on Google before calling.\n\nI have attached a free Google Maps audit report and a short website proposal (PDF). Please have a look.\n\nReport link: {{report_link}}\n\nShall I explain it on a quick call?";
    $em="Hi {{business_name}} team,\n\nI'm {{sender_name}} from {{agency_name}}. We ran a free audit of your website ({{website}}) and your Google Maps listing, and found a few quick wins that can help you get more enquiries from Google.\n\nYour personalised report is attached as a PDF. You can also view it here: {{report_link}}\n\nIf you'd like, I can walk you through it in a short 15-minute call – just reply to this email.\n\nBest regards,\n{{sender_name}}\n{{agency_name}}\n{{agency_phone}} | {{agency_website}}";
    $emn="Hi {{business_name}} team,\n\nI'm {{sender_name}} from {{agency_name}}. While checking businesses on Google Maps for \"{{keyword}}\", we noticed you don't have a website yet.\n\nI've attached a free Google Maps audit report and a short website proposal. You can also view the report here: {{report_link}}\n\nIf you'd like, I can walk you through it in a short 15-minute call – just reply to this email.\n\nBest regards,\n{{sender_name}}\n{{agency_name}}\n{{agency_phone}} | {{agency_website}}";
    return [
      ['report_website','Default – Website & Maps audit','',$web],
      ['report_noweb','Default – No website: Maps audit + website pitch','',$noweb],
      ['whatsapp','Default – WhatsApp first message','',$wa],
      ['whatsapp_noweb','Default – WhatsApp (no website)','',$wan],
      ['email','Default – Email first message','Free audit: how {{business_name}} can get more customers from Google',$em],
      ['email_noweb','Default – Email (no website)','{{business_name}}: free Google Maps audit & website idea',$emn]];}
  static function types(){return ['report_website'=>['Report – has website','AI prompt used to write the PDF report when the business has a website.'],'report_noweb'=>['Report – no website','AI prompt used when the business has no website (website pitch + Maps audit).'],'whatsapp'=>['WhatsApp message','First WhatsApp message sent with the PDF report. Keep it simple – no fees.'],'whatsapp_noweb'=>['WhatsApp – no website','First WhatsApp message for businesses without a website.'],'email'=>['Email message','First email sent with the PDF report attached.'],'email_noweb'=>['Email – no website','First email for businesses without a website (proposal PDF attached).']];}
  static function defaults(){
    $have=array_column(DB::all('SELECT k FROM settings'),'k');
    foreach(self::settings() as $k=>$v)if(!in_array($k,$have,true))Settings::set($k,$v);
    $types=array_column(DB::all('SELECT DISTINCT type FROM prompts'),'type');
    foreach(self::prompts() as [$t,$n,$s,$c])if(!in_array($t,$types,true))DB::insert('prompts',['type'=>$t,'name'=>$n,'subject'=>$s,'content'=>$c,'is_active'=>1,'is_default'=>1]);}}
